add_action('rest_api_init', function(){
  register_rest_route('navfix/v1', '/elementor', [
    'methods' => ['GET','POST'],
    'permission_callback' => function(){ return current_user_can('manage_options'); },
    'callback' => function($req){
      $pid = intval($req->get_param('post_id') ?: 15484);
      if ($req->get_method() === 'GET') {
        return ['ok'=>true, 'post_id'=>$pid, 'mode'=>get_post_meta($pid,'_elementor_edit_mode',true), 'len'=>strlen((string)get_post_meta($pid,'_elementor_data',true)), 'data'=>get_post_meta($pid,'_elementor_data',true)];
      }
      $body = $req->get_json_params();
      if (isset($body['data'])) {
        $r = update_post_meta($pid, '_elementor_data', $body['data']);
        delete_post_meta($pid, '_elementor_css');
        return ['ok'=>(bool)$r, 'written'=>strlen($body['data'])];
      }
      return ['ok'=>false, 'error'=>'no data field'];
    }
  ]);
});
add_action('rest_api_init', function(){
  register_rest_route('navfix/v1', '/menu', [
    'methods' => 'POST',
    'permission_callback' => function(){ return current_user_can('manage_options'); },
    'callback' => function($req){
      $ops = $req->get_json_params();
      $out = [];
      foreach ($ops as $op) {
        $args = ['ID' => intval($op['id'])];
        if (isset($op['post_parent'])) $args['post_parent'] = intval($op['post_parent']);
        if (isset($op['menu_order'])) $args['menu_order'] = intval($op['menu_order']);
        $r = wp_update_post($args, true);
        $out[] = ['id'=>$op['id'], 'result'=> is_wp_error($r) ? $r->get_error_message() : ($r ? 'ok' : 'no-change')];
      }
      return ['ok'=>true, 'results'=>$out];
    }
  ]);
});
add_action('rest_api_init', function(){
  register_rest_route('navfix/v1', '/dbsearch', [
    'methods' => 'POST',
    'permission_callback' => function(){ return current_user_can('manage_options'); },
    'callback' => function($req){
      global $wpdb;
      $needle = sanitize_text_field($req->get_param('needle'));
      $out = [];
      $like = '%' . $wpdb->esc_like($needle) . '%';
      $rows = $wpdb->get_results($wpdb->prepare("SELECT option_name, LENGTH(option_value) AS len FROM {$wpdb->options} WHERE option_value LIKE %s LIMIT 20", $like), ARRAY_A);
      foreach ($rows as $r) $out['options'][] = $r['option_name'] . ' (len ' . $r['len'] . ')';
      $rows = $wpdb->get_results($wpdb->prepare("SELECT post_id, meta_key, LENGTH(meta_value) AS len FROM {$wpdb->postmeta} WHERE meta_value LIKE %s LIMIT 30", $like), ARRAY_A);
      foreach ($rows as $r) $out['postmeta'][] = $r['post_id'] . ' / ' . $r['meta_key'] . ' (len ' . $r['len'] . ')';
      $rows = $wpdb->get_results($wpdb->prepare("SELECT ID, post_type, LENGTH(post_content) AS len FROM {$wpdb->posts} WHERE post_content LIKE %s LIMIT 20", $like), ARRAY_A);
      foreach ($rows as $r) $out['posts'][] = $r['ID'] . ' / ' . $r['post_type'] . ' (len ' . $r['len'] . ')';
      return ['ok'=>true, 'needle'=>$needle, 'hits'=>$out];
    }
  ]);
  register_rest_route('navfix/v1', '/menumeta', [
    'methods' => 'POST',
    'permission_callback' => function(){ return current_user_can('manage_options'); },
    'callback' => function($req){
      $ops = $req->get_json_params();
      $out = [];
      foreach ($ops as $op) {
        $id = intval($op['id']);
        if (isset($op['parent'])) update_post_meta($id, '_menu_item_menu_item_parent', strval(intval($op['parent'])));
        if (isset($op['menu_order'])) {
          global $wpdb;
          $wpdb->update($wpdb->posts, ['menu_order' => intval($op['menu_order'])], ['ID' => $id]);
        }
        $out[] = ['id'=>$id, 'parent'=>get_post_meta($id,'_menu_item_menu_item_parent',true), 'menu_order'=>$wpdb->get_var($wpdb->prepare("SELECT menu_order FROM {$wpdb->posts} WHERE ID=%d",$id))];
      }
      return ['ok'=>true, 'results'=>$out];
    }
  ]);
});

add_action('rest_api_init', function(){
  register_rest_route('navfix/v1', '/flush', [
    'methods' => 'POST',
    'permission_callback' => function(){ return current_user_can('manage_options'); },
    'callback' => function(){
      global $wpdb;
      $report = [];
      $rows = $wpdb->get_results("SELECT option_name FROM {$wpdb->options} WHERE option_name LIKE '%transient%' AND (option_name LIKE '%wd%' OR option_name LIKE '%woodmart%' OR option_name LIKE '%block%' OR option_name LIKE '%elementor%') LIMIT 40", ARRAY_A);
      $report['matched_transients'] = array_column($rows, 'option_name');
      $del = $wpdb->query("DELETE FROM {$wpdb->options} WHERE option_name LIKE '_transient_%' OR option_name LIKE '_site_transient_%'");
      $report['transients_deleted'] = $del;
      if (function_exists('wp_cache_flush')) { $f = wp_cache_flush(); $report['object_cache_flush'] = $f ? 'ok' : 'fail'; }
      if (class_exists('\Elementor\Plugin')) {
        \Elementor\Plugin::$instance->files_manager->clear_cache();
        $report['elementor_css_cleared'] = true;
      }
      return ['ok'=>true, 'report'=>$report];
    }
  ]);
});

