add_action('rest_api_init', function() {
    register_rest_route('smapfix/v1', '/invalidate', array(
        'methods' => 'GET',
        'callback' => function() {
            $out = array();
            if (class_exists('RankMath\Sitemap\Cache')) {
                RankMath\Sitemap\Cache::invalidate();
                $out['rm_cache_invalidated'] = true;
            } else { $out['rm_cache_class'] = 'MISSING'; }
            wp_cache_flush();
            $out['object_cache_flushed'] = true;
            return $out;
        },
        'permission_callback' => function() { return current_user_can('manage_options'); }
    ));
});
